customFunctions:
/*
 * XToys 触觉桥 — 接收端运行时（阶段 0）
 * =====================================================================
 * 本文件被 tools/build-xtoys-script.mjs 嵌入 Script JSON 的 customFunctions
 * 字段，运行在 XToys 的 JS-Interpreter 中。
 *
 * 权威依据：
 *   - 映射与仲裁  docs/03-protocol-mapping.md
 *   - 协议字段    docs/02-webhook-protocol.md
 *   - 数据流      docs/04-architecture-flow.md
 *
 * 硬约束：
 *   - 只能 ES5：var + function。禁止 let/const/=>/class/async/await/
 *     模板字符串/解构/展开。tools/check-es5-subset.mjs 会检查。
 *   - 只写"当前输出值"（setVolume/setDirection）。绝不调用任何设置
 *     设备最大强度 / 最大旋转速度的接口（HANDOFF.md §3.2）。
 *   - 同步返回 != 设备确认（HANDOFF.md §3.4）。措辞不得声称设备已确认。
 *
 * 三条关键设计（讨论定论，不要"顺手优化"掉）：
 *   1. 事件驱动与输出刷新彻底分离：handle 只改状态，输出全部由 tick 计算。
 *   2. 推送判据 = 数值 或 驱动者身份（driveId）变化。不能只比数值，
 *      否则"新事件、强度恰好相同"会被静默吞掉（docs/03 §4.4）。
 *   3. frequency 缺省 = 保持设备当前值，不是置零（docs/03 §4.5）。
 */

/* =====================================================================
 * 1. 宿主 API（XToys 提供；本地测试注入同名 mock）
 *
 * 所有宿主调用都包在 try/catch 里（HANDOFF.md §7.3：try/catch 记一条日志即可）。
 * 这一步不是形式主义：stop_all 的推送循环里如果 setVariable/callAction 抛异常，
 * 异常会冲出 xtoysBridgeHandle —— 游戏侧收不到 ok:false，而剩下的 Block
 * 还停在旧输出上。包住之后，"把归零推出去"这件事不会因为某个通道失败而中断。
 * ===================================================================== */

var XTHB_setVariable_raw = setVariable;
var XTHB_getVariable_raw = getVariable;
var XTHB_callAction_raw = callAction;

/* 所有宿主调用的安全包装。抛异常时记一条日志并返回 false，绝不让异常逃出。 */
function XTHB_setVariable(name, value) {
  try {
    XTHB_setVariable_raw(name, value);
    return true;
  } catch (err) {
    xthbHostErrors = xthbHostErrors + 1;
    xthbLog("setVariable(" + name + ") 抛异常，已吞掉：" + err);
    return false;
  }
}

function XTHB_getVariable(name) {
  try {
    return XTHB_getVariable_raw(name);
  } catch (err) {
    xthbHostErrors = xthbHostErrors + 1;
    xthbLog("getVariable(" + name + ") 抛异常，按未设置处理");
    return null;
  }
}

function XTHB_callAction(action) {
  try {
    XTHB_callAction_raw(action);
    return true;
  } catch (err) {
    xthbHostErrors = xthbHostErrors + 1;
    xthbLog("callAction 抛异常，已吞掉：" + err);
    return false;
  }
}

/* =====================================================================
 * 2. 常量与状态
 * ===================================================================== */

var XTHB_PROTOCOL_VERSION = 1;
var XTHB_VAR_CONFIG = "xthb-config-json";

var XTHB_CMD_PLAY = "play";
var XTHB_CMD_UPDATE = "update";
var XTHB_CMD_STOP = "stop";
var XTHB_CMD_SET_BASELINE = "set_baseline";
var XTHB_CMD_STOP_ALL = "stop_all";
var XTHB_CMD_TEST = "test";

var XTHB_DIR_CLOCKWISE = "clockwise";
var XTHB_DIR_COUNTERCLOCKWISE = "counterclockwise";

/* 边界门：拒绝畸形输入，不是容量管理系统（HANDOFF.md §7.3）。 */
var XTHB_MAX_PAYLOAD_CHARS = 16384;
var XTHB_MAX_TARGETS = 16;
var XTHB_MAX_ID_CHARS = 64;
var XTHB_MAX_DURATION_MS = 600000;
var XTHB_MAX_EVENTS = 64;
/*
 * 事件整体到期后，还保留多久作为序号栅栏（防重复投递变成重复刺激）。
 *
 * 2026-10-07 联调报告建议重新审视这个数字：栅栏真正的语义需求是
 * "重试/重复投递窗口内不被绕过"，那个窗口通常是秒级到分钟级，而不是 10 分钟。
 * 保留期越长，栅栏表越大、内存与查表成本越高。暂维持 10 分钟（保守），
 * 但它不再进 tick 热路径，所以对性能无影响。
 */
var XTHB_EXPIRED_EVENT_KEEP_MS = 600000;
/*
 * 栅栏表条目上限（内存保护，不是语义闸门）。
 * 栅栏不进 tick 热路径，所以这个上限只影响内存与"更早的重放会被漏放"。
 * 一次 34 事件的攻击 × 10 分钟保留期内约 30 次攻击 ≈ 1000 条，故取 4000 留余量。
 */
var XTHB_MAX_FENCE_EVENTS = 4000;
/* 栅栏表清理的最小间隔：保留期是 10 分钟，每秒清一次足够，且不会把成本搬回热路径。 */
var XTHB_FENCE_TRIM_INTERVAL_MS = 1000;
/* 事件计数与计时这类"每 tick 都变"的诊断变量，每多少个 tick 才真正写一次。 */
var XTHB_DIAG_INTERVAL_TICKS = 10;
/* 每多少个 tick 往控制台打一行统计（50 → 约 5 秒一行）。 */
var XTHB_STATS_INTERVAL_TICKS = 50;
/* 测量自检的固定迭代次数（用于判断计时是否可信，见 xthbMeasureSanity）。 */
var XTHB_SANITY_ITERATIONS = 400;
/* 启动没读到配置时，tick 里最多补读多少次（约 3 秒）。 */
var XTHB_MAX_INIT_RETRIES = 30;

/* metric 取值（docs/03 §2.2）。 */
var XTHB_METRIC_ESTIM = "estim";
var XTHB_METRIC_VIBRATE = "vibrate";
var XTHB_METRIC_ROTATE = "rotate";
/* 频率不是 Block 类型，只是 estim Block 上的第二个维度；单独用这个键去仲裁。 */
var XTHB_METRIC_FREQUENCY = "frequency";

/* 解析后的配置。 */
var xthbConfig = null;
/* 由配置派生的"已配置 Block"列表。 */
var xthbBlocks = [];

/* 事件表：source + eventId -> 事件。**只放仍在驱动输出的活跃事件。** */
var xthbEvents = {};
/*
 * 序号栅栏：source + eventId -> { sequence, finishAtMs, expiredAtMs }。
 *
 * 事件到期后从 xthbEvents 移到这里，只保留"防重放"所需的序号信息。
 * 为什么分开（2026-10-07 联调报告问题 1/2）：
 * 过期事件原本留在 xthbEvents 里 10 分钟，而 tick 每个周期要遍历整个容器好几遍
 * （到期清理 + 活跃计数 + 条目计数）。在 JS-Interpreter 里对象遍历与属性访问的
 * 常数因子很大，容器随会话单调增长 → 每 tick 固定成本越来越高 → 82% 的 tick
 * 击穿执行预算，用户侧表现为"越到后面越卡"。
 * 栅栏只需要在【收到同一个 source+eventId 时】查表，不必进热路径。
 */
var xthbEventFence = {};
/* 基线快照：source -> { sequence, parts }。 */
var xthbBaselines = {};
/* 每个 source 的基线序号栅栏（stop_all 清状态但保留它）。 */
var xthbBaselineSeq = {};

/* 上次写下的输出：channel -> { value, frequency, rampSeconds, driveId }。 */
var xthbWritten = {};
/* 是否需要强推一次（初始化与 stop_all 时把归零真正送出去）。 */
var xthbForcePush = false;

/* 诊断计数（措辞必须遵守 HANDOFF.md §3.4）。 */
var xthbTicks = 0;
var xthbCallsOK = 0;
var xthbRejected = 0;
var xthbIgnored = 0;
/* 被吞掉的宿主 API 异常次数。>0 说明 XToys 侧调用出过问题，要去看日志。 */
var xthbHostErrors = 0;
var xthbLastError = "";
var xthbLastIgnored = "";
/* 已留痕过的 (部位, 指标) 组合，避免同一个问题被反复计数。 */
var xthbAuditSeen = {};
/* tick 里"补读配置"的尝试次数（见 xtoysBridgeTick 的自愈分支）。 */
var xthbTickCountForInit = 0;
/* 发现并清理掉的残缺事件条目数（真机崩过一次 finishAtMs TypeError，见 xthbEventEntry）。 */
var xthbCorruptEvents = 0;
/* 从活跃表移入栅栏表的事件数（累计）。 */
var xthbExpiredToFence = 0;

/*
 * tick 分段计时（累计毫秒）。
 *
 * 2026-10-07 联调报告建议"先测量再优化"。第一版只把"仲裁+推送"合在一起测，
 * 结果 37ms 无法判断是"算得慢"还是"写设备慢"。这里拆成三段：
 *   xthbTickComputeMs  —— 仲裁（算每个 Block 该输出什么）
 *   xthbTickPushMs     —— 推送（写变量 + 启动输出 Job）
 *   xthbTickCleanMs    —— 到期搬迁 / 栅栏清理 / 诊断写变量 / 统计日志
 * 三者相加 ≈ tick 总耗时；差值就是剩余的框架开销。
 *
 * ⚠️ 测量可信度：`Date.now()` 在本环境的分辨率与是否被粗化都不明。
 * 所以 xthbLogStats 里同时给出"窗口墙钟跨度"，与累计计时对照；
 * 并对一段固定工作量做自检（见 xthbMeasureSanity），
 * 如果同一段工作在不同窗口报出成倍差异，就说明测量是噪声、不能作为优化依据。
 */
var xthbTickTotalMs = 0;
var xthbTickComputeMs = 0;
var xthbTickPushMs = 0;
var xthbTickCleanMs = 0;
/* 统计窗口起点：上一次打统计时的累计计时与 tick 序号（见 xthbLogStats）。 */
var xthbStatsWinTick = 0;
var xthbStatsWinTotalMs = 0;
var xthbStatsWinComputeMs = 0;
var xthbStatsWinPushMs = 0;
var xthbStatsWinCleanMs = 0;
var xthbStatsWinWallMs = 0;
/* 测量自检上次的读数（用于跨窗口比较）。 */
var xthbSanityPrevMs = -1;
/* 本次初始化用的配置来自哪里（注入 / 回退读变量），以及它的类型与长度。 */
var xthbInjectedInfo = "未知";
/* 诊断变量的上次写入值，用来跳过重复写入（见 xthbWriteDiagnostics）。 */
var xthbDiagCache = {};

/* =====================================================================
 * 3. 基础工具（全部 ES5）
 * ===================================================================== */

function xthbNowMs() {
  if (typeof Date === "undefined") {
    return 0;
  }
  if (typeof Date.now === "function") {
    return Date.now();
  }
  return new Date().getTime();
}

/*
 * 日志。
 *
 * 真机联调（2026-10-05）里一次测试产生 3253 行日志，其中绝大多数是 Job/Action
 * 轨迹与逐条"收到 …"，对定位帮助有限；而控制台日志本身在 JS-Interpreter 里也是开销。
 * 所以给逐条命令日志一个开关：
 *
 *   XTHB_LOG_VERBOSE = false → 只记 rejected / ignored / 异常 / 初始化 / 停止
 *   XTHB_LOG_VERBOSE = true  → 另外记每条命令摘要（排查"为什么没反应"时打开）
 *
 * 注意：rejected / ignored / 初始化 / 停止这些**不经过这里**的过滤 ——
 * 它们是定位问题时必需的信息，任何时候都要有。
 */
var XTHB_LOG_VERBOSE = false;

function xthbLog(text) {
  try {
    if (typeof console !== "undefined" && console && console.log) {
      console.log("[xthb] " + text);
    }
  } catch (logErr) {
    /* 日志失败不影响业务，也不写任何硬件状态。 */
  }
}

/* 逐条命令摘要：只在 verbose 打开时输出。 */
function xthbLogVerbose(text) {
  if (XTHB_LOG_VERBOSE) {
    xthbLog(text);
  }
}

function xthbIsFiniteNumber(value) {
  if (typeof value !== "number") {
    return false;
  }
  if (value !== value) {
    return false;
  }
  if (value === Infinity || value === -Infinity) {
    return false;
  }
  return true;
}

function xthbClamp(value, low, high) {
  if (value < low) {
    return low;
  }
  if (value > high) {
    return high;
  }
  return value;
}

/* 返回夹取后的数字；非法（含显式 null）返回 null。 */
function xthbRequireNumber(value, low, high) {
  if (!xthbIsFiniteNumber(value)) {
    return null;
  }
  return xthbClamp(value, low, high);
}

function xthbIsNonEmptyString(value) {
  return typeof value === "string" && value.length > 0;
}

/*
 * source / eventId 是事件身份的一部分，内部用 \u0000 当分隔符做键。
 * 如果 ID 本身含控制字符，(source,eventId) 就会互相碰撞 —— 例如
 * source="a\u0000b"/eventId="c" 与 source="a"/eventId="b\u0000c" 会撞在同一个键上，
 * 违反 docs/02 §2「不同 source 可用相同 eventId 而互不影响」。
 * 所以 ID 一律禁止控制字符（这是畸形输入，直接拒绝）。
 */
function xthbIsSafeId(value, maxChars) {
  var index;
  var code;
  if (!xthbIsNonEmptyString(value) || value.length > maxChars) {
    return false;
  }
  for (index = 0; index < value.length; index = index + 1) {
    code = value.charCodeAt(index);
    if (code < 32 || code === 127) {
      return false;
    }
  }
  return true;
}

function xthbIsArray(value) {
  return typeof value === "object" && value !== null &&
    typeof value.length === "number" && typeof value.push === "function";
}

/* 去掉 BOM 与首尾空白。XToys 写变量时可能带上它们，会让 JSON.parse 直接失败。 */
function xthbTrimRaw(text) {
  var start = 0;
  var end = text.length;
  var code;
  while (start < end) {
    code = text.charCodeAt(start);
    if (code === 0xFEFF || code === 32 || code === 9 || code === 10 || code === 13) {
      start = start + 1;
    } else {
      break;
    }
  }
  while (end > start) {
    code = text.charCodeAt(end - 1);
    if (code === 32 || code === 9 || code === 10 || code === 13) {
      end = end - 1;
    } else {
      break;
    }
  }
  return text.substring(start, end);
}

/* 把实际读到的文本做成一行可读的预览，用于诊断"配置不是合法 JSON"。 */
function xthbPreview(text) {
  var visible = text.length > 160 ? text.substring(0, 160) + "…(截断)" : text;
  var out = "";
  var index;
  var code;
  for (index = 0; index < visible.length; index = index + 1) {
    code = visible.charCodeAt(index);
    if (code < 32) {
      out = out + "\\u" + ("000" + code.toString(16)).slice(-4);
    } else {
      out = out + visible.charAt(index);
    }
  }
  return "\"" + out + "\"";
}

function xthbHasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function xthbCountOwn(obj) {
  var total = 0;
  var key;
  for (key in obj) {
    if (xthbHasOwn(obj, key)) {
      total = total + 1;
    }
  }
  return total;
}

function xthbOwnKeys(obj) {
  var keys = [];
  var key;
  for (key in obj) {
    if (xthbHasOwn(obj, key)) {
      keys.push(key);
    }
  }
  return keys;
}

function xthbCanonicalDirection(value) {
  var lowered;
  if (!xthbIsNonEmptyString(value)) {
    return null;
  }
  lowered = value.toLowerCase();
  if (lowered === "clockwise") {
    return XTHB_DIR_CLOCKWISE;
  }
  if (lowered === "counterclockwise") {
    return XTHB_DIR_COUNTERCLOCKWISE;
  }
  return null;
}

function xthbFail(code, detail) {
  var message = detail ? code + ": " + detail : code;
  xthbRejected = xthbRejected + 1;
  xthbLastError = message;
  xthbLog("rejected " + message);
  return { ok: false, code: code };
}

/* 忽略留痕：部位合法但本部署没接那类设备（docs/03 §6.2.2）。 */
function xthbNoteIgnored(detail) {
  xthbIgnored = xthbIgnored + 1;
  xthbLastIgnored = detail;
  xthbLog("ignored " + detail);
}

/* =====================================================================
 * 4. 配置解析与校验
 * ===================================================================== */

/*
 * 配置 JSON（Initial Actions 写入 xthb-config-json）：
 *   {
 *     "protocolVersion": 1,
 *     "knownParts": ["nipple", ...],   // 配置校验用，不是载荷白名单
 *     "parts": { "<part>": { "estim": "<channelId>", "vibrate": ..., "rotate": ... } },
 *     "frequencySentinel": -1
 *   }
 *
 * 校验规则（违反则拒绝初始化，docs/03 §3）：
 *   1. 每个 Channel ID 只能出现在一个 part 下（Block 专属一个 part）。
 *   2. part 名必须是非空字符串（没有白名单；表里有的就是合法的）。
 *   3. metric 必须是 estim / vibrate / rotate。
 */
/*
 * 解析配置。
 *
 * rawOverride 用于"启动时变量还没就绪"的补救：如果 Initial Actions 里
 * updateVariable 与 customCode 的先后顺序在 XToys 实际执行时不能保证，
 * init 就读不到配置；此时留到 tick 里用 getVariable 再读一次（见 xtoysBridgeTick）。
 */
function xthbParseConfig(injected) {
  var raw;
  var parsed;

  /*
   * 注入值可能是字符串（JSON 文本）也可能是对象（XToys 直接求值/反序列化后）。
   * 两种都接受 —— 真机上到底是哪种我们无法预先断定，没必要为此让运行时停摆。
   */
  if (injected !== undefined && injected !== null) {
    if (typeof injected === "object" && !xthbIsArray(injected)) {
      return xthbValidateConfig(injected);
    }
    raw = injected;
  } else {
    raw = XTHB_getVariable(XTHB_VAR_CONFIG);
    if (typeof raw === "object" && raw !== null && !xthbIsArray(raw)) {
      return xthbValidateConfig(raw);
    }
  }

  if (!xthbIsNonEmptyString(raw)) {
    return { error: "配置未就绪或类型不支持（读到 " + xthbPreview(String(raw)) + "）" };
  }
  /* 去掉 BOM 与首尾空白 —— 它们会让 JSON.parse 直接失败。 */
  raw = xthbTrimRaw(raw);
  try {
    parsed = JSON.parse(raw);
  } catch (parseErr) {
    /*
     * 把实际读到的内容打出来（截断 + 转义）。没有这一步，"配置不是合法 JSON"
     * 只能靠猜：到底是空值、被截断、还是被 XToys 改写过。
     * 真机实测就是靠这条日志定位到"494 字符被打成 91 字符、值全变 undefined"的。
     */
    return { error: "配置不是合法 JSON（读到 " + raw.length + " 字符：" + xthbPreview(raw) + "）" };
  }
  return xthbValidateConfig(parsed);
}

/*
 * 校验已经解析成对象的配置，并派生出 Block 列表。
 *
 * 支持两种形状（键名大小写与长短都不敏感，避免为了省几个字符而把解析写脆）：
 *   完整版：{ protocolVersion, parts: { part: { metric: channelId } }, frequencySentinel }
 *   紧凑版：{ v, p: { part: [metric, ...] }, s }
 * 紧凑版是生成器内联进 code 的那个；完整版是备路变量里的那个。
 */
function xthbValidateConfig(parsed) {
  var blocks = [];
  var seen = {};
  var part;
  var metric;
  var partSpec;
  var id;
  var partsSpec = xthbPickKey(parsed, ["parts", "p"]);
  var sentinel = xthbPickKey(parsed, ["frequencySentinel", "s"]);
  var version = xthbPickKey(parsed, ["protocolVersion", "v"]);
  var metricList;
  var metricIndex;

  if (version === undefined) {
    /* 没写版本就按当前版本处理：紧凑配置刻意省掉它。 */
    version = XTHB_PROTOCOL_VERSION;
  }
  if (version !== XTHB_PROTOCOL_VERSION) {
    return { error: "配置 protocolVersion 不受支持（读到 " + xthbPreview(String(version)) + "）" };
  }
  if (typeof partsSpec !== "object" || partsSpec === null) {
    return { error: "配置缺少 parts（读到 " + xthbPreview(xthbPreview2(parsed)) + "）" };
  }
  if (xthbCountOwn(partsSpec) === 0) {
    return { error: "配置 parts 为空" };
  }
  if (!xthbIsFiniteNumber(sentinel)) {
    return { error: "配置缺少 frequencySentinel" };
  }
  /*
   * 哨兵值必须在真实频率范围（0–100）之外，否则"没有频率意图"与"真实频率值"
   * 无法区分，estim Job 会在每次推送时都去写频率（docs/03 §4.5）。
   */
  if (sentinel >= 0 && sentinel <= 100) {
    return { error: "配置 frequencySentinel 必须落在 0–100 之外" };
  }

  for (part in partsSpec) {
    if (!xthbHasOwn(partsSpec, part)) {
      continue;
    }
    if (!xthbIsNonEmptyString(part)) {
      return { error: "parts 含非法部位名" };
    }
    /*
     * 不校验"部位名是否在合法清单里"。docs/03 §6.1 定的是：
     * 部位名是否可用，完全由这张映射表决定 —— 表里有就是合法的，没有白名单。
     */
    if (!xthbIsSafeId(part, XTHB_MAX_ID_CHARS)) {
      return { error: "parts 含控制字符或过长的部位名" };
    }
    partSpec = partsSpec[part];

    if (xthbIsArray(partSpec)) {
      /* 紧凑版：该部位启用的 metric 列表。 */
      metricList = partSpec;
    } else if (typeof partSpec === "object" && partSpec !== null) {
      /* 完整版：metric → channelId。 */
      metricList = xthbOwnKeys(partSpec);
    } else {
      return { error: "parts." + part + " 既不是 metric 列表也不是对象" };
    }

    for (metricIndex = 0; metricIndex < metricList.length; metricIndex = metricIndex + 1) {
      metric = metricList[metricIndex];
      if (metric !== XTHB_METRIC_ESTIM && metric !== XTHB_METRIC_VIBRATE &&
        metric !== XTHB_METRIC_ROTATE) {
        return { error: "parts." + part + " 含未知 metric " + metric };
      }
      /*
       * 完整版配置显式给出 Channel ID；紧凑版没有，就按命名规范推导。
       * 显式给了就必须用它 —— 这样"Block 专属一个 part"的校验对两种形状都有效。
       */
      id = xthbConfigChannelValue(partSpec, metric);
      if (!xthbIsNonEmptyString(id)) {
        id = channelIdFor(metric, part);
      }
      /* 规则 1：Block 专属一个 part。 */
      if (xthbHasOwn(seen, id)) {
        return { error: "Channel " + id + " 同时属于 " + seen[id] + " 与 " + part };
      }
      seen[id] = part;
      blocks.push({
        part: part,
        metric: metric,
        channel: id,
        volumeVar: xthbVolumeVar(id),
        rampVar: xthbRampVar(id),
        frequencyVar: metric === XTHB_METRIC_ESTIM ? xthbFrequencyVar(id) : null,
        directionVar: metric === XTHB_METRIC_ROTATE ? xthbDirectionVar(id) : null
      });
    }
  }
  if (blocks.length === 0) {
    return { error: "配置没有派生任何 Block" };
  }
  return { config: { frequencySentinel: sentinel }, blocks: blocks };
}

/* 完整版配置里 metric → Channel ID 的值；紧凑版（数组）没有，返回 undefined。 */
function xthbConfigChannelValue(partSpec, metric) {
  if (xthbIsArray(partSpec)) {
    return undefined;
  }
  return xthbPickKey(partSpec, [metric]);
}

/* 安全序列化：JSON.stringify 不可用时退回 String()，绝不因为诊断而抛异常。 */
function xthbSafeStringify(value) {
  if (xthbIsNonEmptyString(value)) {
    return value;
  }
  try {
    if (typeof JSON !== "undefined" && JSON && typeof JSON.stringify === "function") {
      return JSON.stringify(value);
    }
  } catch (err) {
    /* 落到下面的兜底 */
  }
  return String(value);
}

/* 大小写不敏感地取第一个存在的键。 */
function xthbPickKey(obj, names) {
  var index;
  var key;
  var lowered;
  for (index = 0; index < names.length; index = index + 1) {
    if (xthbHasOwn(obj, names[index])) {
      return obj[names[index]];
    }
    lowered = names[index].toLowerCase();
    for (key in obj) {
      if (xthbHasOwn(obj, key) && key.toLowerCase() === lowered) {
        return obj[key];
      }
    }
  }
  return undefined;
}

/* 把一个对象做成简短可读的预览，用于诊断。 */
function xthbPreview2(obj) {
  var keys = xthbOwnKeys(obj);
  return "{" + keys.join(",") + "}";
}

/* 该 metric 在这个部位上有没有 Block。没有 → 忽略该指标（docs/03 §6.2）。 */
function xthbBlocksFor(part, metric) {
  var out = [];
  var index;
  for (index = 0; index < xthbBlocks.length; index = index + 1) {
    if (xthbBlocks[index].part === part && xthbBlocks[index].metric === metric) {
      out.push(xthbBlocks[index]);
    }
  }
  return out;
}

/* 该部位在这个 metric 上有没有 Block。没有 → 该指标被忽略并留痕。 */
function xthbPartTakesMetric(part, metric) {
  return xthbBlocksFor(part, metric).length > 0;
}

function xthbHasPart(part) {
  var index;
  for (index = 0; index < xthbBlocks.length; index = index + 1) {
    if (xthbBlocks[index].part === part) {
      return true;
    }
  }
  return false;
}

/*
 * 变量名从 Channel ID 派生（与生成器命名规范一致，docs/03 §2.1）：
 *   part-estim-nipple     → xthb-estim-nipple-volume
 *   part-vibrator-nipple  → xthb-vibrator-nipple-volume
 *   part-rotator-nipple   → xthb-rotator-nipple-volume
 * 注意这里是 "vibrator"/"rotator"（通道类型用词），不是 metric 名 "vibrate"/"rotate"。
 * 以 Channel ID 为唯一真源，避免同一个 Block 出现两套名字。
 */
function xthbChannelSlug(channelId) {
  if (channelId.indexOf("part-") === 0) {
    return channelId.substring(5);
  }
  return channelId;
}

function xthbVolumeVar(channelId) {
  return "xthb-" + xthbChannelSlug(channelId) + "-volume";
}

function xthbRampVar(channelId) {
  return "xthb-" + xthbChannelSlug(channelId) + "-ramp-seconds";
}

function xthbFrequencyVar(channelId) {
  return "xthb-" + xthbChannelSlug(channelId) + "-frequency";
}

function xthbDirectionVar(channelId) {
  return "xthb-" + xthbChannelSlug(channelId) + "-direction-code";
}

/* metric + part → Channel ID。规则见 docs/03 §2.1（通道类型词用 vibrator / rotator）。 */
var XTHB_METRIC_CHANNEL_WORD = {
  estim: "estim",
  vibrate: "vibrator",
  rotate: "rotator"
};

function channelIdFor(metric, part) {
  var word = xthbHasOwn(XTHB_METRIC_CHANNEL_WORD, metric)
    ? XTHB_METRIC_CHANNEL_WORD[metric]
    : metric;
  return "part-" + word + "-" + part;
}

/* 输出 Job 名由 metric + part 派生（与生成器一致）。 */
function xthbOutputJobFor(block) {
  return "xthb-output-" + block.metric + "-" + block.part;
}

/* =====================================================================
 * 5. targets 解析
 * ===================================================================== */

function xthbParseTarget(raw, index, requireDriveMetric) {
  var target = {};

  if (typeof raw !== "object" || raw === null || xthbIsArray(raw)) {
    return { error: "targets[" + index + "] 不是对象" };
  }
  /*
   * part 只要求非空字符串。部位名是否可用由映射配置决定，
   * 未识别的部位走"忽略并留痕"，不是整体拒绝（docs/03 §6.1）。
   */
  if (!xthbIsNonEmptyString(raw.part)) {
    return { error: "targets[" + index + "].part 必须是字符串" };
  }
  target.part = raw.part;

  /*
   * 强度按通道分开（协议 2026-10-05 决定）：
   *   estimIntensity   → 该部位的 estim Block
   *   vibrateIntensity → 该部位的 vibrate Block
   * 已删除旧的单一 `intensity` 字段 —— 它会让"同一部位同时用 estim 与 vibrate"
   * 的设备无法分别控制（用户明确要求分开，以便适配这类双模设备）。
   */
  if (xthbHasOwn(raw, "estimIntensity")) {
    target.estimIntensity = xthbRequireNumber(raw.estimIntensity, 0, 100);
    if (target.estimIntensity === null) {
      return { error: "targets[" + index + "].estimIntensity 非法" };
    }
  }
  if (xthbHasOwn(raw, "vibrateIntensity")) {
    target.vibrateIntensity = xthbRequireNumber(raw.vibrateIntensity, 0, 100);
    if (target.vibrateIntensity === null) {
      return { error: "targets[" + index + "].vibrateIntensity 非法" };
    }
  }
  if (xthbHasOwn(raw, "frequency")) {
    target.frequency = xthbRequireNumber(raw.frequency, 0, 100);
    if (target.frequency === null) {
      return { error: "targets[" + index + "].frequency 非法" };
    }
  }
  if (xthbHasOwn(raw, "rotateSpeed")) {
    target.rotateSpeed = xthbRequireNumber(raw.rotateSpeed, 0, 100);
    if (target.rotateSpeed === null) {
      return { error: "targets[" + index + "].rotateSpeed 非法" };
    }
  }
  if (xthbHasOwn(raw, "rotateDirection")) {
    target.rotateDirection = xthbCanonicalDirection(raw.rotateDirection);
    if (target.rotateDirection === null) {
      return { error: "invalid_rotate_direction" };
    }
  }

  /* rotateSpeed > 0 必须给方向；== 0 表示停旋转，方向可省（docs/03 §6.2）。 */
  if (xthbHasOwn(target, "rotateSpeed") && target.rotateSpeed > 0 &&
    !xthbHasOwn(target, "rotateDirection")) {
    return { error: "rotateSpeed > 0 时必须有 rotateDirection" };
  }

  /* 驱动指标一个都没有 → 畸形输入（含只带 rotateDirection 的情况）。
   * 注意 frequency 算驱动指标：它独立驱动 estim Block 的频率维度（见 §4.5）。 */
  if (requireDriveMetric &&
    !xthbHasOwn(target, "estimIntensity") && !xthbHasOwn(target, "vibrateIntensity") &&
    !xthbHasOwn(target, "frequency") && !xthbHasOwn(target, "rotateSpeed")) {
    return { error: "targets[" + index + "] 没有任何驱动指标" };
  }

  if (xthbHasOwn(raw, "durationMs")) {
    target.durationMs = xthbRequireNumber(raw.durationMs, 0, XTHB_MAX_DURATION_MS);
    if (target.durationMs === null) {
      return { error: "targets[" + index + "].durationMs 非法" };
    }
  }
  if (xthbHasOwn(raw, "rampUpMs")) {
    target.rampUpMs = xthbRequireNumber(raw.rampUpMs, 0, XTHB_MAX_DURATION_MS);
    if (target.rampUpMs === null) {
      return { error: "targets[" + index + "].rampUpMs 非法" };
    }
  }
  if (xthbHasOwn(raw, "rampDownMs")) {
    target.rampDownMs = xthbRequireNumber(raw.rampDownMs, 0, XTHB_MAX_DURATION_MS);
    if (target.rampDownMs === null) {
      return { error: "targets[" + index + "].rampDownMs 非法" };
    }
  }
  if (xthbHasOwn(raw, "priority")) {
    target.priority = xthbRequireNumber(raw.priority, -1000000, 1000000);
    if (target.priority === null) {
      return { error: "targets[" + index + "].priority 非法" };
    }
  }
  return { target: target };
}

/*
 * 解析 targets。
 * requireDriveMetric：
 *   true  —— play / update / set_baseline / test 的"意图"，必须至少有一个驱动指标。
 *   false —— stop 的"选择器"，只需要指出哪个部位，不需要也不应该有指标
 *            （"{part:'nipple'}" 是合法的 stop 选择器，见 docs/02 §5）。
 */
function xthbParseTargets(raw, requireDriveMetric) {
  var out = [];
  var parsed;
  var index;
  var seenPart = {};

  if (!xthbIsArray(raw)) {
    return { error: "targets 不是数组" };
  }
  if (raw.length > XTHB_MAX_TARGETS) {
    return { error: "targets 超过 " + XTHB_MAX_TARGETS + " 条" };
  }
  for (index = 0; index < raw.length; index = index + 1) {
    parsed = xthbParseTarget(raw[index], index, requireDriveMetric);
    if (parsed.error) {
      return { error: parsed.error };
    }
    /* 一个部位只出现一次；重复会造成静默覆盖，是数组语法问题（docs/03 §6.5）。 */
    if (xthbHasOwn(seenPart, parsed.target.part)) {
      return { error: "targets 里部位 " + parsed.target.part + " 重复出现" };
    }
    seenPart[parsed.target.part] = true;
    out.push(parsed.target);
  }
  return { targets: out };
}

/* 把 targets 转成 part -> 意图 的表。 */
function xthbTargetsToParts(targets) {
  var map = {};
  var index;
  for (index = 0; index < targets.length; index = index + 1) {
    map[targets[index].part] = targets[index];
  }
  return map;
}

/* =====================================================================
 * 6. 状态：有限事件与基线快照
 * ===================================================================== */

function xthbEventKey(source, eventId) {
  return source + "\u0000" + eventId;
}

function xthbRemoveEvent(source, eventId) {
  var key = xthbEventKey(source, eventId);
  if (xthbHasOwn(xthbEvents, key)) {
    delete xthbEvents[key];
  }
}

/*
 * 事件容器的"完整性校验"：拿到一个可用的事件条目，否则返回 null。
 *
 * 为什么需要它：真机联调日志里出现过
 *   TypeError: Cannot read property 'finishAtMs' of undefined
 * 抛出点在 tick 内。静态检查没能定位出必然路径，但**生产代码在真机崩过一次，
 * 就不能只靠推理说"不可能"** —— 所以所有读取点统一走这个守卫：
 * 条目缺失或字段不完整时直接当"不存在"处理并清掉，绝不让它把 tick 打断。
 */
function xthbEventEntry(key) {
  var e;
  if (!xthbHasOwn(xthbEvents, key)) {
    return null;
  }
  e = xthbEvents[key];
  if (!e || typeof e !== "object" ||
    typeof e.finishAtMs !== "number" ||
    typeof e.parts !== "object" || e.parts === null) {
    /* 残缺条目：清理掉，避免每次 tick 都在这里呛一下。 */
    delete xthbEvents[key];
    xthbNoteCorruptEvent();
    return null;
  }
  if (typeof e.partFinishAtMs !== "object" || e.partFinishAtMs === null) {
    /* partFinishAtMs 缺失不致命：回退到事件级到期时刻。 */
    e.partFinishAtMs = {};
    xthbNoteCorruptEvent();
  }
  return e;
}

function xthbNoteCorruptEvent() {
  xthbCorruptEvents = xthbCorruptEvents + 1;
  xthbLastError = "corrupt_event";
  xthbLog("发现残缺事件条目，已清理（累计 " + xthbCorruptEvents + "）");
}

function xthbApplyPlay(source, eventId, sequence, parts, finishAtMs, partFinishAtMs) {
  var key = xthbEventKey(source, eventId);
  var existing = xthbEventEntry(key);
  var fence;
  var seqInFence;

  /*
   * 序号栅栏查两处：活跃事件表 与 栅栏表。
   * 两者合起来才等于"这个身份见过的最大 sequence"。
   */
  fence = xthbHasOwn(xthbEventFence, key) ? xthbEventFence[key] : null;
  seqInFence = (fence && typeof fence.sequence === "number") ? fence.sequence : -Infinity;

  /* 身份 = source + eventId；只有严格更大的 sequence 才替换（协议 §2）。 */
  if (existing && sequence <= existing.sequence) {
    return { ok: false, code: "invalid_sequence" };
  }
  if (sequence <= seqInFence) {
    return { ok: false, code: "invalid_sequence" };
  }
  /*
   * 容量闸门只看【活跃事件表】—— 栅栏不占容量。
   * 真机实测（2026-10-05）：一次"攻击纹理"产生 34 个独立 eventId、durationMs
   * 只有 250–700ms，用容器条目数当闸门会让每次攻击占掉 34 个 10 分钟名额，
   * 第 3 次起就被拒，越用越死。
   */
  if (!existing && xthbCountOwn(xthbEvents) >= XTHB_MAX_EVENTS) {
    /*
     * 到顶了。先把"已经到期但还没被 tick 搬走"的事件立刻挪进栅栏表，再判一次。
     *
     * 为什么需要这一步：到期搬迁原本只发生在 tick 里（每 100ms）。如果一批命令
     * 挤在两次 tick 之间到达，上一批明明已经到期的事件还挂在活跃表里占名额，
     * 新命令就会被误拒。这里做一次廉价的前置清理，避免"明明空闲却被拒"。
     */
    xthbMoveExpiredToFence(xthbNowMs());
    if (xthbCountOwn(xthbEvents) >= XTHB_MAX_EVENTS) {
      /*
       * 带上数字：否则无法从日志区分"真的事件风暴"与"栅栏堆积"。
       */
      xthbLog("容量拒绝：live=" + xthbCountOwn(xthbEvents) +
        " fence=" + xthbCountOwn(xthbEventFence) +
        " max=" + XTHB_MAX_EVENTS + "（eventId=" + eventId + "）");
      return { ok: false, code: "state_capacity_exceeded" };
    }
  }
  /* 更高的 sequence 到达 → 旧栅栏条目使命结束，可以让位。 */
  if (fence !== null) {
    delete xthbEventFence[key];
  }
  xthbTrimFence();
  xthbEvents[key] = {
    source: source,
    eventId: eventId,
    sequence: sequence,
    parts: parts,
    /* 事件整体到期时刻 = max(各部位)，用于内存清理与序号栅栏保留期。 */
    finishAtMs: finishAtMs,
    /* 每个部位自己的到期时刻 —— 到期必须按部位判定（docs/02 §3）。 */
    partFinishAtMs: partFinishAtMs,
    /* 已不再驱动任何输出的时刻；此后只作为序号栅栏保留，供重试载荷判定新旧。 */
    expiredAtMs: -1
  };
  return { ok: true, code: "accepted" };
}

/* 形式 1：只给 eventId → 整个事件；2：eventId+targets → 事件的这些部位；
 * 3：只给 targets → 该来源所有事件的这些部位。 */
function xthbApplyStop(source, eventId, parts) {
  var key;
  var event;
  var partNames;
  var index;
  var removed = 0;
  /* 独立循环变量与"待删清单"，避免复用外层变量 / 边遍历边删。 */
  var stopKey;
  var stopEvent;
  var deadKeys;

  if (eventId !== null && parts === null) {
    if (!xthbHasOwn(xthbEvents, xthbEventKey(source, eventId))) {
      return { ok: false, code: "missing_stop_selector" };
    }
    xthbRemoveEvent(source, eventId);
    return { ok: true, code: "stopped_event" };
  }
  if (parts === null) {
    return { ok: false, code: "missing_stop_selector" };
  }

  partNames = xthbOwnKeys(parts);

  if (eventId !== null) {
    key = xthbEventKey(source, eventId);
    if (!xthbHasOwn(xthbEvents, key)) {
      return { ok: false, code: "missing_stop_selector" };
    }
    event = xthbEvents[key];
    for (index = 0; index < partNames.length; index = index + 1) {
      if (xthbHasOwn(event.parts, partNames[index])) {
        delete event.parts[partNames[index]];
        removed = removed + 1;
      }
    }
    /*
     * 先判断是否真的移除了东西，再决定清理空壳事件。
     * 反过来写会让"什么都没匹配到"的失败命令仍然删掉一个空事件 ——
     * 被拒绝的命令绝不能改变状态。
     */
    if (removed === 0) {
      return { ok: false, code: "missing_stop_selector" };
    }
    if (xthbCountOwn(event.parts) === 0) {
      xthbRemoveEvent(source, eventId);
    }
    return { ok: true, code: "stopped_parts" };
  }

  /*
   * 收集所有该来源的事件、移除指定部位；空壳事件先记下、最后统一删。
   *
   * 不用"边遍历边 delete"，也不复用外层循环变量（真机报告指出过这两点隐患：
   * 在部分解释器下边遍历边删会跳过/重复元素，复用变量会污染外层逻辑）。
   */
  deadKeys = [];
  for (stopKey in xthbEvents) {
    if (!xthbHasOwn(xthbEvents, stopKey)) {
      continue;
    }
    stopEvent = xthbEventEntry(stopKey);
    if (stopEvent === null) {
      continue;
    }
    if (stopEvent.source !== source) {
      continue;
    }
    for (index = 0; index < partNames.length; index = index + 1) {
      if (xthbHasOwn(stopEvent.parts, partNames[index])) {
        delete stopEvent.parts[partNames[index]];
        removed = removed + 1;
      }
    }
    if (xthbCountOwn(stopEvent.parts) === 0) {
      deadKeys.push(stopKey);
    }
  }
  if (removed === 0) {
    return { ok: false, code: "missing_stop_selector" };
  }
  /* 移除成功后才清理空壳事件。 */
  for (index = 0; index < deadKeys.length; index = index + 1) {
    delete xthbEvents[deadKeys[index]];
  }
  return { ok: true, code: "stopped_parts" };
}

function xthbApplyBaseline(source, sequence, parts) {
  /* 序号栅栏：stop_all 清状态但保留它，所以必须继续递增（协议 §2）。 */
  if (xthbHasOwn(xthbBaselineSeq, source) && sequence <= xthbBaselineSeq[source]) {
    return { ok: false, code: "invalid_sequence" };
  }
  /* 基线是完整快照，不是叠加：新快照替换旧快照，遗漏的部位被清除。 */
  xthbBaselines[source] = { sequence: sequence, parts: parts };
  xthbBaselineSeq[source] = sequence;
  return { ok: true, code: "accepted" };
}

/* =====================================================================
 * 7. 仲裁与输出计算（docs/03 §4 / §5）
 * ===================================================================== */

function xthbIntentPriority(intent) {
  if (xthbIsFiniteNumber(intent.priority)) {
    return intent.priority;
  }
  return 0;
}

/*
 * 该意图在这个 metric 下的仲裁值；不参与 → null。
 *
 * 强度按通道分开（2026-10-05 协议改动）：
 *   estim   ← estimIntensity
 *   vibrate ← vibrateIntensity
 *   rotate  ← rotateSpeed
 *   frequency 是 estim 上的第二个维度，独立仲裁（见 xthbComputeBlock）。
 */
function xthbMetricValue(intent, metric) {
  if (metric === XTHB_METRIC_ESTIM) {
    if (xthbIsFiniteNumber(intent.estimIntensity)) {
      return intent.estimIntensity;
    }
    return null;
  }
  if (metric === XTHB_METRIC_VIBRATE) {
    if (xthbIsFiniteNumber(intent.vibrateIntensity)) {
      return intent.vibrateIntensity;
    }
    return null;
  }
  if (metric === XTHB_METRIC_FREQUENCY) {
    if (xthbIsFiniteNumber(intent.frequency)) {
      return intent.frequency;
    }
    return null;
  }
  if (metric === XTHB_METRIC_ROTATE) {
    if (xthbIsFiniteNumber(intent.rotateSpeed)) {
      return intent.rotateSpeed;
    }
    return null;
  }
  return null;
}

/*
 * 收集某部位在某 metric 下的候选：该部位的基线意图 ∪ 该部位所有【未到期】事件的意图。
 *
 * 到期按【每个部位各自】判定：一个事件里 nipple 的 durationMs=200、clitoris 的
 * durationMs=5000 时，nipple 必须在 200ms 后就不再参与仲裁（docs/02 §3 把
 * durationMs 定义在 target 上）。早期实现把整个事件按 max(durationMs) 过期，
 * 会让 200ms 的一击持续输出 5 秒。
 */
/*
 * 候选收集缓存（每个 tick 内有效）。
 *
 * 同一个 (part, metric) 在一次 tick 里会被问两次 —— 一次为音量、一次为频率
 * （estim Block 的 frequency 维度独立仲裁）。真机上出现过
 * "JavaScript did not finish running in allotted time"，而 JS-Interpreter 里
 * 每次收集都要遍历基线与事件表，所以这里按 (part, metric) 记住结果。
 */
var xthbCandidateCache = null;

function xthbResetCandidateCache() {
  xthbCandidateCache = {};
}

function xthbCollectCandidates(part, metric, nowMs) {
  var key = part + "\u0000" + metric;
  if (xthbCandidateCache !== null && xthbHasOwn(xthbCandidateCache, key)) {
    return xthbCandidateCache[key];
  }
  var candidates = xthbCollectCandidatesUncached(part, metric, nowMs);
  if (xthbCandidateCache !== null) {
    xthbCandidateCache[key] = candidates;
  }
  return candidates;
}

function xthbCollectCandidatesUncached(part, metric, nowMs) {
  var candidates = [];
  var source;
  var key;
  var event;
  var intent;
  var value;
  var finishAt;

  for (source in xthbBaselines) {
    if (!xthbHasOwn(xthbBaselines, source)) {
      continue;
    }
    intent = xthbBaselines[source].parts[part];
    if (!intent) {
      continue;
    }
    value = xthbMetricValue(intent, metric);
    if (value === null) {
      continue;
    }
    candidates.push({
      value: value,
      priority: xthbIntentPriority(intent),
      sequence: xthbBaselines[source].sequence,
      driveId: source + "\u0000\u0000" + xthbBaselines[source].sequence,
      source: source,
      intent: intent
    });
  }

  for (key in xthbEvents) {
    if (!xthbHasOwn(xthbEvents, key)) {
      continue;
    }
    /* 完整性守卫：残缺条目不参与仲裁（也是 tick 崩溃的可能位置之一）。 */
    event = xthbEventEntry(key);
    if (event === null) {
      continue;
    }
    intent = event.parts[part];
    if (!intent) {
      continue;
    }
    /* 每个部位自己的到期时刻；partFinishAtMs 缺失时回退到事件级。 */
    finishAt = xthbHasOwn(event.partFinishAtMs, part)
      ? event.partFinishAtMs[part] : event.finishAtMs;
    if (typeof finishAt !== "number") {
      finishAt = event.finishAtMs;
    }
    if (finishAt <= nowMs) {
      continue;
    }
    value = xthbMetricValue(intent, metric);
    if (value === null) {
      continue;
    }
    candidates.push({
      value: value,
      priority: xthbIntentPriority(intent),
      sequence: event.sequence,
      driveId: event.source + "\u0000" + event.eventId + "\u0000" + event.sequence,
      source: event.source,
      intent: intent
    });
  }
  return candidates;
}

/* 三级比较：priority → 数值 → sequence（docs/03 §5）。 */
function xthbPickBetter(candidate, incumbent) {
  if (incumbent === null) {
    return true;
  }
  if (candidate.priority !== incumbent.priority) {
    return candidate.priority > incumbent.priority;
  }
  if (candidate.value !== incumbent.value) {
    return candidate.value > incumbent.value;
  }
  if (candidate.sequence !== incumbent.sequence) {
    return candidate.sequence > incumbent.sequence;
  }
  /* 完全并列时按 driveId 定序，保证结果确定。 */
  return candidate.driveId > incumbent.driveId;
}

function xthbArbitrate(part, metric, nowMs) {
  var candidates = xthbCollectCandidates(part, metric, nowMs);
  var winner = null;
  var index;
  for (index = 0; index < candidates.length; index = index + 1) {
    if (xthbPickBetter(candidates[index], winner)) {
      winner = candidates[index];
    }
  }
  return winner;
}

/*
 * ramp 秒数：value <= 0 用 rampDownMs，否则 rampUpMs。
 * rampTime 单位在 docs/01 §4.2 仍标 ⚠️未独立验证（变量名暗示秒）。
 * 若不是秒，只改这一个函数。
 */
function xthbRampSeconds(intent, value) {
  var ms = 0;
  if (value <= 0) {
    if (xthbIsFiniteNumber(intent.rampDownMs)) {
      ms = intent.rampDownMs;
    }
  } else if (xthbIsFiniteNumber(intent.rampUpMs)) {
    ms = intent.rampUpMs;
  }
  if (ms < 0) {
    ms = 0;
  }
  return ms / 1000;
}

function xthbDirectionCode(intent) {
  if (intent.rotateDirection === XTHB_DIR_CLOCKWISE) {
    return 1;
  }
  if (intent.rotateDirection === XTHB_DIR_COUNTERCLOCKWISE) {
    return -1;
  }
  return 0;
}

/*
 * 算出一个 Block 当前应该输出什么。
 *
 * 强度按通道分开读（2026-10-05 协议改动）：
 *   - estim Block   ← estimIntensity（音量）+ frequency（频率，独立仲裁）
 *   - vibrate Block ← vibrateIntensity（音量）
 *   - rotate Block  ← rotateSpeed（速度）+ 方向
 * value / frequency 各自可"未驱动"：未驱动时写哨兵值，输出 Job 的条件 Action
 * 就不会去碰设备上的那一项。
 */
function xthbComputeBlock(block, nowMs) {
  var winner = xthbArbitrate(block.part, block.metric, nowMs);
  var out = {
    channel: block.channel,
    block: block,
    value: 0,
    valueDriven: false,
    frequency: null,
    direction: 0,
    rampSeconds: 0,
    driveId: ""
  };
  var hasIntensity;
  var freqWinner;

  if (winner === null) {
    /* 没有候选：音量归零（这个部位确实不该输出）。 */
    out.valueDriven = true;
    out.value = 0;
    return out;
  }
  out.driveId = winner.driveId;

  if (block.metric === XTHB_METRIC_ESTIM) {
    hasIntensity = xthbIsFiniteNumber(winner.intent.estimIntensity);
    if (hasIntensity) {
      out.valueDriven = true;
      out.value = winner.intent.estimIntensity;
      out.rampSeconds = xthbRampSeconds(winner.intent, out.value);
    }
    /*
     * 频率维度独立仲裁：音量 winner 没给 frequency 时，不能就此把频率当成
     * "未指定" —— 同一部位可能有另一个（更强的）意图在明确要求频率。
     * 两者都带 frequency 时结果一致（同一个意图会在两个维度都胜出），
     * 只有音量 winner 缺 frequency 时才会由另一个意图补上。
     */
    freqWinner = winner;
    if (!xthbIsFiniteNumber(winner.intent.frequency)) {
      freqWinner = xthbArbitrate(block.part, XTHB_METRIC_FREQUENCY, nowMs);
      if (freqWinner === null) {
        freqWinner = winner;
      }
    }
    if (xthbIsFiniteNumber(freqWinner.intent.frequency)) {
      out.frequency = freqWinner.intent.frequency;
    }
    /* 只有频率意图（没有 estimIntensity）时 valueDriven 保持 false：
     * 这次只动频率，音量变量根本不写 —— 否则会把正在输出的强度拽到 0。 */
    return out;
  }

  out.valueDriven = true;
  out.value = winner.value;
  out.rampSeconds = xthbRampSeconds(winner.intent, winner.value);
  if (block.metric === XTHB_METRIC_ROTATE) {
    out.direction = xthbDirectionCode(winner.intent);
  }
  return out;
}

function xthbComputeOutputs(nowMs) {
  var outs = [];
  var index;
  for (index = 0; index < xthbBlocks.length; index = index + 1) {
    outs.push(xthbComputeBlock(xthbBlocks[index], nowMs));
  }
  return outs;
}

/*
 * 忽略留痕（docs/03 §6.1 / §6.2）。
 *
 * 在【接受命令时】逐个 target 判定，而不是在 tick 里反复判定：
 *   1. tick 里判定会把计数变成"tick 数"，而且一个持续 10 秒的未知部位会在
 *      100ms 节奏下刷 100 条日志，把真正的错误淹掉；
 *   2. 短暂事件（durationMs 很小）会在下一次 tick 之前就到期，
 *      在 tick 里根本看不到它 —— 游戏侧拼错部位名就完全不会留下痕迹。
 *
 * 同一个 (部位, 指标) 只记一次，避免重复计数。
 */
function xthbNoteTargetIgnores(targets, context) {
  var index;
  var metricIndex;
  var target;
  var part;
  var metrics = [XTHB_METRIC_ESTIM, XTHB_METRIC_VIBRATE, XTHB_METRIC_ROTATE];
  var metric;
  var flagKey;

  for (index = 0; index < targets.length; index = index + 1) {
    target = targets[index];
    part = target.part;
    if (!xthbHasPart(part)) {
      flagKey = "part|" + part;
      if (!xthbHasOwn(xthbAuditSeen, flagKey)) {
        xthbAuditSeen[flagKey] = true;
        xthbNoteIgnored("部位 " + part + " 未在映射配置里（" + context + "）");
      }
      continue;
    }
    for (metricIndex = 0; metricIndex < metrics.length; metricIndex = metricIndex + 1) {
      metric = metrics[metricIndex];
      if (!xthbTargetCarriesMetric(target, metric)) {
        continue;
      }
      if (!xthbPartTakesMetric(part, metric)) {
        flagKey = part + "|" + metric;
        if (!xthbHasOwn(xthbAuditSeen, flagKey)) {
          xthbAuditSeen[flagKey] = true;
          xthbNoteIgnored(part + " 没有 " + metric + " 对应的 Block，该指标被忽略（" + context + "）");
        }
      }
    }
  }
}

/* 这条 target 是否带了这个指标（决定它需要不需要对应的 Block）。 */
function xthbTargetCarriesMetric(target, metric) {
  if (metric === XTHB_METRIC_ESTIM) {
    return xthbIsFiniteNumber(target.estimIntensity) || xthbIsFiniteNumber(target.frequency);
  }
  if (metric === XTHB_METRIC_VIBRATE) {
    /* 振动只消费 vibrateIntensity；没有 vibrate Block 时它无处可去。 */
    return xthbIsFiniteNumber(target.vibrateIntensity);
  }
  if (metric === XTHB_METRIC_ROTATE) {
    return xthbIsFiniteNumber(target.rotateSpeed);
  }
  return false;
}

/* =====================================================================
 * 8. 推送：写变量 + 启动输出 Job（docs/03 §4.4）
 * ===================================================================== */

/*
 * 记入 xthbWritten 时统一把"本次不驱动频率"存成同一个哨兵值。
 * 绝不能一边存 null、一边存哨兵值 —— 那样 xthbNeedsPush 会把"没变"误判成
 * "变了"，每个 tick 都重复启动输出 Job（这个坑真踩过一次）。
 */
function xthbRecordedFrequency(out) {
  if (out.frequency === null) {
    return xthbConfig.frequencySentinel;
  }
  return out.frequency;
}

/*
 * 推送判据：数值 或 驱动者身份变化。不能只比数值 —— 否则"新事件、强度恰好
 * 与当前相同"会被静默吞掉。ramp 是设备级动作，重跑输出 Job 才会重新走一遍
 * rampTime，这正是连击需要的重触发。
 */
function xthbNeedsPush(out) {
  var last = xthbHasOwn(xthbWritten, out.channel) ? xthbWritten[out.channel] : null;
  var frequency;
  if (last === null) {
    return true;
  }
  frequency = xthbRecordedFrequency(out);
  if (last.valueDriven !== out.valueDriven) {
    return true;
  }
  if (out.valueDriven) {
    if (last.value !== out.value) {
      return true;
    }
    if (last.rampSeconds !== out.rampSeconds) {
      return true;
    }
  }
  if (last.frequency !== frequency) {
    return true;
  }
  if (last.driveId !== out.driveId) {
    return true;
  }
  return false;
}

function xthbPushOutputs(outs) {
  var pushed = 0;
  var index;
  var out;
  var force = xthbForcePush;

  xthbForcePush = false;

  for (index = 0; index < outs.length; index = index + 1) {
    out = outs[index];
    if (!force && !xthbNeedsPush(out)) {
      continue;
    }
    /*
     * 音量只在"这次确实有音量意图"时写。频率-only 的意图不碰音量变量，
     * 否则会把正在输出的强度拽到 0。
     */
    if (out.valueDriven) {
      XTHB_setVariable(out.block.volumeVar, out.value);
      XTHB_setVariable(out.block.rampVar, out.rampSeconds);
    }
    if (out.block.frequencyVar !== null) {
      /* null → 哨兵值：明确表示"本次不动频率"。 */
      XTHB_setVariable(out.block.frequencyVar,
        out.frequency === null ? xthbConfig.frequencySentinel : out.frequency);
    }
    if (out.block.directionVar !== null) {
      XTHB_setVariable(out.block.directionVar, out.direction);
    }
    /*
     * 唤醒输出 Job。成功只表示 callAction 没有同步抛异常，
     * 不代表 Job 执行了、更不代表设备收到了（HANDOFF.md §3.4）。
     */
    XTHB_callAction({ type: "updateJob", job: xthbOutputJobFor(out.block), action: "start" });
    xthbWritten[out.channel] = {
      value: out.value,
      valueDriven: out.valueDriven,
      rampSeconds: out.rampSeconds,
      frequency: xthbRecordedFrequency(out),
      driveId: out.driveId
    };
    pushed = pushed + 1;
  }
  return pushed;
}

/*
 * 把所有输出变量写成零，并把这份零状态记入 xthbWritten。
 *
 * 必须记入 xthbWritten：stop_all / 停止函数刚把零推给输出 Job 之后，
 * 下一个 tick 不应该再原样重推一遍。之前这里清空 xthbWritten，会让
 * 每次 tick 都认为"值变了"而重复启动 9 个输出 Job。
 */
function xthbWriteZerosAndRecord() {
  var index;
  var block;
  for (index = 0; index < xthbBlocks.length; index = index + 1) {
    block = xthbBlocks[index];
    XTHB_setVariable(block.volumeVar, 0);
    XTHB_setVariable(block.rampVar, 0);
    if (block.frequencyVar !== null) {
      /* 频率不动：写哨兵值，让输出 Job 不去碰设备频率。 */
      XTHB_setVariable(block.frequencyVar, xthbConfig.frequencySentinel);
    }
    if (block.directionVar !== null) {
      XTHB_setVariable(block.directionVar, 0);
    }
    xthbWritten[block.channel] = {
      value: 0,
      valueDriven: true,
      rampSeconds: 0,
      frequency: xthbConfig.frequencySentinel,
      driveId: ""
    };
  }
}

/* =====================================================================
 * 9. 入口：初始化 / tick / 载荷 / 停止
 * ===================================================================== */

function xthbCountParts() {
  var seen = {};
  var total = 0;
  var index;
  for (index = 0; index < xthbBlocks.length; index = index + 1) {
    if (!xthbHasOwn(seen, xthbBlocks[index].part)) {
      seen[xthbBlocks[index].part] = true;
      total = total + 1;
    }
  }
  return total;
}

/*
 * 初始化。
 *
 * injectedConfig：Initial Actions 通过 customCode 的 variables 直接注入的配置。
 *   ——这是【主路】，与触发器传 payload 用的是同一机制（真机已验证可用）。
 * 没有注入值时才回退去读 Script 变量 xthb-config-json（备路 + tick 补读）。
 *
 * 真机实测教训（2026-09-30）：只靠 updateVariable 写变量、JS 再 getVariable 读回来，
 * 在真机上读到的内容会被打坏（长度 494 → 91，值全变成 undefined），
 * 于是初始化失败、运行时静默、所有 webhook 无反应。所以必须有一条不依赖它的路。
 */
function xtoysBridgeInit(injectedConfig) {
  var quoted;
  var parsed = xthbParseConfig(injectedConfig);

  if (injectedConfig !== undefined && injectedConfig !== null) {
    /*
     * 诊断：记录注入值的类型与【序列化后的长度】，用于核对传值是否完整。
     * 这里必须用 JSON.stringify，不能用 String() —— 真机实测（2026-09-30）：
     * XToys 的 String(普通对象) 返回 "[object Object]"，正好 15 个字符，
     * 于是日志显示"配置来源：object/15字符"，看起来像配置被截断了，
     * 实际完全正常（同一次日志里 Block 9 个就是证明）。别再踩这个坑。
     */
    quoted = xthbSafeStringify(injectedConfig);
    xthbInjectedInfo = (typeof injectedConfig) + "/" + (quoted ? quoted.length : 0) + "字符";
  } else {
    xthbInjectedInfo = "未注入（回退读变量）";
  }

  xthbEvents = {};
  xthbEventFence = {};
  xthbBaselines = {};
  xthbBaselineSeq = {};
  xthbWritten = {};
  xthbBlocks = [];
  xthbConfig = null;
  xthbForcePush = false;
  xthbTicks = 0;
  xthbCallsOK = 0;
  xthbRejected = 0;
  xthbIgnored = 0;
  xthbLastError = "";
  xthbLastIgnored = "";
  xthbAuditSeen = {};
  xthbHostErrors = 0;

  if (parsed.error) {
    /* 配置错误：tick 保持静默、不驱动任何输出；音量归零由 Initial Actions 负责。 */
    xthbLog("init 失败：" + parsed.error + " —— 运行时静默，不会驱动任何输出");
    XTHB_setVariable("xthb-status", "config_error");
    XTHB_setVariable("xthb-last-error", parsed.error);
    return "config_error";
  }

  xthbConfig = parsed.config;
  xthbBlocks = parsed.blocks;

  /* 先把所有输出变量写成零，避免上一次运行的残留值被输出 Job 读走。 */
  xthbWriteZerosAndRecord();
  xthbWritten = {};
  /* 第一次 tick 强推一次全零，确保输出 Job 真的把零写出去。 */
  xthbForcePush = true;
  XTHB_setVariable("xthb-status", "running");
  xthbLog("初始化完成：部位 " + xthbCountParts() + " 个，Block " + xthbBlocks.length +
    " 个（配置来源：" + xthbInjectedInfo + "）");
  /*
   * 把两个开关的可发现性写进日志：真机排查时用户看不到变量面板，
   * 如果不知道有这两个开关，就无从下手。
   */
  xthbLog("排查提示：每 " + XTHB_STATS_INTERVAL_TICKS + " 个 tick 打一行统计（含分段耗时与测量自检）；" +
    "逐条命令日志默认关闭，需要时把 XTHB_LOG_VERBOSE 设为 true");
  /*
   * 预热一次测量自检并记下基线：否则第一个统计窗口会报"首次"，
   * 而"固定工作量耗时在窗口之间是否稳定"正是判断测量可信度的依据。
   */
  xthbSanityPrevMs = xthbMeasureSanity().ms;
  return "initialized";
}

/* 100 ms 调度 Job 调这个。只计算、比较、必要时写变量 + 启动输出 Job。 */
function xtoysBridgeTick() {
  var nowMs;
  var key;
  var evKey;
  var event;
  var tickStartMs;
  var tickT0;
  var tickT1;
  var outputs;

  /*
   * 自愈：如果启动时没读到配置（Initial Actions 里 updateVariable 与 customCode
   * 的实际执行顺序若不能保证，就会发生），不要就此永久静默 —— 定期重新尝试读一次
   * 配置变量，读到了就自动完成初始化。
   *
   * 真机实测（2026-09-30）遇到的正是这种情况：启动时报"配置不是合法 JSON"，
   * 之后所有 webhook 都因为"运行时未初始化"而无反应。让 tick 自愈可以修掉它，
   * 而且不管根因是顺序问题还是变量写入延迟都成立。
   *
   * 30 次（约 3 秒）还没读到就放弃重试，避免每 100ms 刷日志；但**不停止** tick，
   * 这样真机日志里能明确看到"配置始终没就绪"，而不是一片沉默。
   */
  if (xthbConfig === null) {
    if (xthbTickCountForInit < XTHB_MAX_INIT_RETRIES) {
      xthbTickCountForInit = xthbTickCountForInit + 1;
      if (xtoysBridgeInit() !== "initialized") {
        return "not_initialized";
      }
      xthbLog("配置在 tick 里补读成功（第 " + xthbTickCountForInit + " 次尝试）");
    } else {
      return "not_initialized";
    }
  }
  nowMs = xthbNowMs();
  tickStartMs = nowMs;
  xthbTicks = xthbTicks + 1;
  xthbResetCandidateCache();

  /*
   * 到期处理：
   *   1. 部位各自到期 → 该部位不再参与仲裁（输出回落到基线）。
   *   2. 事件整体到期 → **从活跃表移到栅栏表**，只保留序号信息。
   *      这样 tick 的热路径只遍历活跃事件；栅栏（10 分钟保留）不再拖慢每个周期。
   *   3. 栅栏表自己按保留期清理（同一函数里做，低频）。
   *
   * 保留栅栏是有意的：重试/重复投递的 webhook 若带旧 sequence 必须被拒，
   * 否则一次重复投递就会变成重复刺激（docs/02 §2 的严格递增语义）。
   */
  xthbMoveExpiredToFence(nowMs);
  xthbTrimFence();
  tickT1 = xthbNowMs();
  xthbTickCleanMs = xthbTickCleanMs + (tickT1 - tickStartMs);

  /*
   * 三段分别计时。上一版把"仲裁+推送"合在一起测，得到 37ms 却无法判断
   * 是"算得慢"还是"写设备慢" —— 所以务必分开。
   */
  tickT0 = xthbNowMs();
  outputs = xthbComputeOutputs(nowMs);
  tickT1 = xthbNowMs();
  xthbTickComputeMs = xthbTickComputeMs + (tickT1 - tickT0);

  xthbPushOutputs(outputs);
  tickT0 = xthbNowMs();
  xthbTickPushMs = xthbTickPushMs + (tickT0 - tickT1);

  XTHB_setVariable("xthb-status", "running");
  xthbWriteDiagnostics();
  xthbTickCleanMs = xthbTickCleanMs + (xthbNowMs() - tickT0);

  /*
   * 总耗时只累计到诊断写完为止，**统计日志本身不计入**：
   * 否则日志会把自己算进去，读数偏大。代价是总耗时略小于真实 tick 耗时，
   * 但差值固定且很小（每 50 个 tick 才一行日志）。
   */
  xthbTickTotalMs = xthbTickTotalMs + (xthbNowMs() - tickStartMs);
  xthbLogStats();
  return "tick";
}

/*
 * 测量自检：跑一段固定的、已知规模的工作，返回它消耗的毫秒数。
 *
 * 用途：如果同一段固定工作在不同统计窗口报出成倍差异，说明计时本身不可信
 * （时钟被粗化/被钳制，或解释器调度让测量失真），那么任何"耗时归因"都不能采信。
 * 这段工作刻意只用属性访问与算术，不碰任何状态，保证可重复。
 */
function xthbMeasureSanity() {
  var probe = { a: 1, b: 2, c: 3, d: 4, e: 5, f: 6, g: 7, h: 8 };
  var i;
  var acc = 0;
  var t0 = xthbNowMs();
  for (i = 0; i < XTHB_SANITY_ITERATIONS; i = i + 1) {
    acc = acc + probe.a + probe.b + probe.c + probe.d +
      probe.e + probe.f + probe.g + probe.h;
  }
  return { ms: xthbNowMs() - t0, acc: acc };
}

/*
 * 周期性统计日志（默认开启）。
 *
 * 为什么需要它：计时数据写在 Script 变量里，而 setVariable **不打日志**，
 * 用户界面里也看不到变量面板 —— 于是"为了排查而加的仪表"用户根本读不到。
 * 这里把它们定期打进控制台日志。
 *
 * ⚠️ 计时方式很关键：**按窗口累计，而不是每 tick 各自取差**。
 * `Date.now()` 在本环境只有毫秒分辨率，单 tick 耗时往往不足 1ms，
 * 逐 tick 取差会被全部截断成 0（第一版就是这么错的，读数恒为 0，等于没装仪表）。
 * 现在改为：窗口结束时用 (累计差 / 窗口内 tick 数) 得平均值。
 *
 * 同时给出三项交叉校验，用于判断测量本身是否可信：
 *   wall   —— 本窗口的真实墙钟跨度
 *   total  —— 本窗口累计的 tick 计时之和（与 wall 对照）
 *   sanity —— 一段固定工作的耗时（与上一窗口对照，差异大即测量不可信）
 */
function xthbLogStats() {
  var windowTicks;
  var nowMs;
  var wallMs;
  var sumMs;
  var sanity;
  var sanityNote;
  var line;

  if (xthbTicks <= 0 || xthbTicks % XTHB_STATS_INTERVAL_TICKS !== 0) {
    return;
  }
  windowTicks = xthbTicks - xthbStatsWinTick;
  if (windowTicks <= 0) {
    return;
  }
  nowMs = xthbNowMs();
  wallMs = nowMs - xthbStatsWinWallMs;
  sumMs = xthbTickTotalMs - xthbStatsWinTotalMs;
  sanity = xthbMeasureSanity();

  /*
   * 第一个窗口的墙钟跨度**不可信**：起始点是 0，而启动过程（配置解析、9 个 Block
   * 构建、Initial Actions）本身可能耗掉很久，于是 wallMs 变成一个巨大的数。
   * 真机日志里第一个窗口就出现过这种情况，导致"每 tick 1.42ms"这个异常小的读数 ——
   * 那是被巨大的分母拉低的假象。这里明确标出来，避免有人拿它当基线。
   */
  if (xthbStatsWinWallMs <= 0) {
    wallMs = -1;
  }

  if (xthbSanityPrevMs < 0) {
    /* 正常情况下 init 里已预热过；走到这里说明自检从未跑成，按"未知"标注。 */
    sanityNote = "首次";
  } else if (sanity.ms <= 0 && xthbSanityPrevMs <= 0) {
    sanityNote = "0(时钟分辨率不足)";
  } else if (xthbSanityPrevMs > 0 &&
    (sanity.ms > xthbSanityPrevMs * 3 || sanity.ms * 3 < xthbSanityPrevMs)) {
    sanityNote = "⚠️波动大(测量不可信)";
  } else {
    sanityNote = "稳定";
  }
  xthbSanityPrevMs = sanity.ms;

  line = "统计 tick=" + xthbTicks +
    " 每tick均值=" + xthbRound2(sumMs / windowTicks) + "ms" +
    " [仲裁=" + xthbRound2((xthbTickComputeMs - xthbStatsWinComputeMs) / windowTicks) +
    " 推送=" + xthbRound2((xthbTickPushMs - xthbStatsWinPushMs) / windowTicks) +
    " 清理诊断=" + xthbRound2((xthbTickCleanMs - xthbStatsWinCleanMs) / windowTicks) + "]ms" +
    " 窗口墙钟=" + (wallMs < 0 ? "首个窗口不可信" : xthbRound2(wallMs) + "ms") +
    " 计时和=" + xthbRound2(sumMs) + "ms" +
    " 自检=" + sanity.ms + "ms(" + sanityNote + ")" +
    " 活跃=" + xthbCountOwn(xthbEvents) +
    " 栅栏=" + xthbCountFenceEvents() +
    " 残缺=" + xthbCorruptEvents +
    " 被拒=" + xthbRejected +
    " 宿主异常=" + xthbHostErrors;
  xthbLog(line);

  xthbStatsWinTick = xthbTicks;
  xthbStatsWinTotalMs = xthbTickTotalMs;
  xthbStatsWinComputeMs = xthbTickComputeMs;
  xthbStatsWinPushMs = xthbTickPushMs;
  xthbStatsWinCleanMs = xthbTickCleanMs;
  xthbStatsWinWallMs = nowMs;
}

/* 保留两位小数，避免日志里出现一长串浮点尾数。 */
function xthbRound2(value) {
  return Math.round(value * 100) / 100;
}

/*
 * 诊断变量：只在值真的变化时才写（xthbSetDiag 里有值缓存）。
 *
 * 真机实测（2026-09-30）：原本每个 tick（100ms）无条件写 9 个诊断变量，
 * XToys 控制台每条命令前都出现 "JavaScript did not finish running in allotted time" ——
 * 在 JS-Interpreter 里 10Hz × N 次 setVariable 是实打实的开销。
 *
 * 2026-10-07 第二次联调报告指出：新增的计时变量是**单调累计值**，几乎每个 tick
 * 都在变 → 缓存失效 → 每 tick 真实写变量。所以计时用的累计值改为**每 10 个 tick
 * 才写一次**（用 xthb-tick-count 的模判断），单次成本降一个数量级，
 * 而累计量本来就只需要看趋势。
 *
 * 顺序也有讲究：**先把开销小的、低频的写完，再写计时值**，这样即使本次调用
 * 在计时写完之后才超时，也不会影响关键诊断的可读性。
 */
function xthbWriteDiagnostics() {
  xthbSetDiag("xthb-calls-ok", xthbCallsOK);
  xthbSetDiag("xthb-rejected-count", xthbRejected);
  xthbSetDiag("xthb-ignored-count", xthbIgnored);
  xthbSetDiag("xthb-host-errors", xthbHostErrors);
  xthbSetDiag("xthb-corrupt-events", xthbCorruptEvents);
  xthbSetDiag("xthb-last-error", xthbLastError);
  xthbSetDiag("xthb-last-ignored", xthbLastIgnored);

  /* 每 XTHB_DIAG_INTERVAL_TICKS 个 tick 刷一次事件计数与计时（这些值每 tick 都在变）。 */
  if (xthbTicks % XTHB_DIAG_INTERVAL_TICKS === 0) {
    xthbSetDiag("xthb-tick-count", xthbTicks);
    xthbSetDiag("xthb-active-events", xthbCountOwn(xthbEvents));
    xthbSetDiag("xthb-fence-events", xthbCountFenceEvents());
    xthbSetDiag("xthb-tick-total-ms", xthbTickTotalMs);
    xthbSetDiag("xthb-tick-compute-ms", xthbTickComputeMs);
    xthbSetDiag("xthb-tick-push-ms", xthbTickPushMs);
    xthbSetDiag("xthb-tick-clean-ms", xthbTickCleanMs);
  }
}

function xthbSetDiag(name, value) {
  if (xthbHasOwn(xthbDiagCache, name) && xthbDiagCache[name] === value) {
    return;
  }
  xthbDiagCache[name] = value;
  XTHB_setVariable(name, value);
}

/*
 * 把已到期的事件从活跃表搬进栅栏表。
 * tick 每个周期调一次；xthbApplyPlay 在容量到顶时也会调一次（前置清理）。
 */
function xthbMoveExpiredToFence(nowMs) {
  var key;
  var event;
  var moved = 0;
  for (key in xthbEvents) {
    if (!xthbHasOwn(xthbEvents, key)) {
      continue;
    }
    event = xthbEventEntry(key);
    if (event === null) {
      continue;
    }
    if (event.finishAtMs <= nowMs) {
      xthbEventFence[key] = {
        sequence: event.sequence,
        finishAtMs: event.finishAtMs,
        expiredAtMs: nowMs
      };
      delete xthbEvents[key];
      xthbExpiredToFence = xthbExpiredToFence + 1;
      moved = moved + 1;
    }
  }
  return moved;
}

/* 栅栏表条目数（含已过期但仍需防重放的）。 */
function xthbCountFenceEvents() {
  return xthbCountOwn(xthbEventFence);
}

/*
 * 栅栏表清理：把超过保留期的条目删掉；并做总量上限保护。
 *
 * ⚠️ 刻意【节流】为低频执行：栅栏表可以有上千条，如果每个 tick 都扫一遍，
 * 就等于把刚移出热路径的成本又搬了回来（2026-10-07 报告问题 2 的同一个坑）。
 * 保留期是 10 分钟，每秒清一次完全够用。
 */
var xthbLastFenceTrimMs = -1;

function xthbTrimFence() {
  var key;
  var entry;
  var nowMs = xthbNowMs();
  var total = 0;

  if (xthbLastFenceTrimMs >= 0 && nowMs - xthbLastFenceTrimMs < XTHB_FENCE_TRIM_INTERVAL_MS) {
    return;
  }
  xthbLastFenceTrimMs = nowMs;

  for (key in xthbEventFence) {
    if (!xthbHasOwn(xthbEventFence, key)) {
      continue;
    }
    entry = xthbEventFence[key];
    if (!entry || typeof entry.sequence !== "number") {
      delete xthbEventFence[key];
      continue;
    }
    if (nowMs - entry.expiredAtMs > XTHB_EXPIRED_EVENT_KEEP_MS) {
      delete xthbEventFence[key];
      continue;
    }
    total = total + 1;
  }
  if (total >= XTHB_MAX_FENCE_EVENTS) {
    xthbEvictOldestFence(nowMs);
  }
}

/* 栅栏表达上限时淘汰最老的条目（只影响"更早的重放会被漏放"，不影响活跃输出）。 */
function xthbEvictOldestFence(nowMs) {
  var oldestKey = null;
  var oldestAt = Infinity;
  var key;
  var entry;
  var surplus = xthbCountOwn(xthbEventFence) - XTHB_MAX_FENCE_EVENTS + 1;

  while (surplus > 0) {
    oldestKey = null;
    oldestAt = Infinity;
    for (key in xthbEventFence) {
      if (!xthbHasOwn(xthbEventFence, key)) {
        continue;
      }
      entry = xthbEventFence[key];
      if (entry && entry.expiredAtMs < oldestAt) {
        oldestAt = entry.expiredAtMs;
        oldestKey = key;
      }
    }
    if (oldestKey === null) {
      return;
    }
    delete xthbEventFence[oldestKey];
    surplus = surplus - 1;
  }
}

/*
 * 容器条目总数的硬上限保护（内存，不是语义闸门）。
 * 超限时**优先清掉最老的过期条目**，先保活跃事件、再保最近的栅栏。
 */
/*
 * 命令摘要：只打印解析后的关键字段，不打印整段原文。
 *
 * 原来的写法是 `收到载荷 N 字符："<前 160 字符原文>…"`，真机上既慢又难读，
 * 而且那个 … 容易被误认为 XToys 截断了数据（截断是我自己加的）。
 * 关键字段足够定位问题。
 */
function xthbDescribeCommand(inner) {
  var parts = [];
  var targets;
  var index;
  var names = [];
  parts.push("command=" + String(xthbPickKey(inner, ["command"])));
  parts.push("source=" + String(xthbPickKey(inner, ["source"])));
  if (xthbHasOwn(inner, "eventId")) {
    parts.push("eventId=" + String(inner.eventId));
  }
  if (xthbHasOwn(inner, "sequence")) {
    parts.push("seq=" + String(inner.sequence));
  }
  targets = xthbPickKey(inner, ["targets"]);
  if (xthbIsArray(targets)) {
    parts.push("targets=" + targets.length);
    for (index = 0; index < targets.length && index < 4; index = index + 1) {
      if (targets[index] && xthbIsNonEmptyString(targets[index].part)) {
        names.push(targets[index].part);
      }
    }
    if (names.length > 0) {
      parts.push("parts=" + names.join("+"));
    }
  }
  return parts.join(" ");
}

/*
 * 全局 Trigger 入口。
 * 参数是 Trigger 注入的载荷，真机上可能是【外层封装】也可能已经是【内层载荷】；
 * 两种形状都必须能处理（docs/02 §1 的封装仍要支持，因为手工 curl 测试就是那个形状）。
 */
function xtoysBridgeHandle(payload) {
  var outer;
  var inner;
  var parsed;
  var result;
  var rawLen;

  if (xthbConfig === null) {
    return xthbFail("invalid_config", "运行时未初始化");
  }
  if (typeof payload !== "string" && typeof payload !== "object") {
    return xthbFail("invalid_payload", "载荷既不是字符串也不是对象");
  }
  /* 对象是宿主直接给的情况：无需解析，直接当内层用。 */
  if (typeof payload === "object" && payload !== null) {
    inner = payload;
  } else {
    rawLen = payload.length;
    if (rawLen === 0) {
      return xthbFail("invalid_payload", "载荷为空");
    }
    if (rawLen > XTHB_MAX_PAYLOAD_CHARS) {
      return xthbFail("invalid_payload", "载荷超过 " + XTHB_MAX_PAYLOAD_CHARS + " 字符");
    }
    try {
      outer = JSON.parse(payload);
    } catch (outerErr) {
      xthbLog("载荷不是合法 JSON（" + rawLen + " 字符）");
      return xthbFail("invalid_json", "载荷不是合法 JSON");
    }
    if (typeof outer !== "object" || outer === null) {
      return xthbFail("invalid_payload", "载荷不是对象");
    }
    inner = xthbNormalizeEnvelope(outer);
    if (inner.error) {
      xthbLog("载荷无法识别（" + rawLen + " 字符）：" + xthbPreview(payload));
      return xthbFail(inner.error);
    }
    inner = inner.inner;
  }

  if (typeof inner !== "object" || inner === null) {
    return xthbFail("invalid_payload", "内层不是对象");
  }
  xthbLogVerbose("收到 " + xthbDescribeCommand(inner));

  parsed = xthbParseCommand(inner);
  if (parsed.error) {
    return xthbFail(parsed.error);
  }
  /* 执行阶段的失败必须如实返回 ok:false，绝不能当成成功。 */
  result = xthbExecute(parsed);
  if (result.ok) {
    xthbCallsOK = xthbCallsOK + 1;
  } else {
    xthbRejected = xthbRejected + 1;
    xthbLastError = result.code;
    xthbLog("rejected " + result.code);
  }
  return result;
}

/*
 * 把解析出来的外层对象归一化成协议对象（内层）。
 *
 * 支持这些形状（真机与手工 curl 测试会分别命中不同的那种）：
 *   1. {"action":"xtoys_game_bridge","payload":"<内层JSON文本>"}   协议 §1 的封装
 *   2. {"action":"xtoys_game_bridge","payload":{...}}              payload 已被求值成对象
 *   3. {"command":"...","source":"..."}                            已是内层协议对象
 *   4. "<内层JSON文本>"                                             双重编码的字符串
 * 返回 null 表示无法识别。
 */
function xthbNormalizeEnvelope(outer) {
  var action = xthbPickKey(outer, ["action"]);
  var innerRaw;
  var depth = 0;
  var current = outer;

  if (xthbIsNonEmptyString(action) && action !== "xtoys_game_bridge") {
    xthbLog("载荷 action 不是 xtoys_game_bridge（读到 " + xthbPreview(String(action)) + "）");
    return { error: "invalid_payload" };
  }
  if (xthbHasOwn(outer, "payload") || xthbHasOwn(outer, "Payload")) {
    innerRaw = xthbPickKey(outer, ["payload"]);
    if (typeof innerRaw === "string") {
      try {
        current = JSON.parse(innerRaw);
      } catch (innerErr) {
        xthbLog("外层 payload 不是合法 JSON（读到 " + xthbPreview(innerRaw) + "）");
        /* payload 字段本身不是合法 JSON → 这是 JSON 解析失败，不是结构不认识。 */
        return { error: "invalid_json" };
      }
    } else if (typeof innerRaw === "object" && innerRaw !== null) {
      current = innerRaw;
    } else {
      return { error: "invalid_payload" };
    }
  }
  /*
   * 兜底：还有可能是"字符串里再套一层字符串"（双重编码）。最多解 4 层，
   * 既处理真实情况又不会死循环。
   */
  while (typeof current === "string" && depth < 4) {
    try {
      current = JSON.parse(current);
    } catch (againErr) {
      return { error: "invalid_json" };
    }
    depth = depth + 1;
  }
  if (typeof current !== "object" || current === null) {
    return { error: "invalid_payload" };
  }
  /* 认一下是不是协议对象：至少要有个 command 或 targets。 */
  if (!xthbHasOwn(current, "command") && !xthbHasOwn(current, "targets") &&
    !xthbHasOwn(current, "Command")) {
    return { error: "invalid_payload" };
  }
  return { inner: current };
}

function xthbParseCommand(inner) {
  var command;
  var targets = null;
  var seq = null;
  var durationMs = 0;
  var maxDuration = 0;
  var hasEventId;
  var index;

  if (inner.protocolVersion !== XTHB_PROTOCOL_VERSION) {
    return { error: "unsupported_protocol_version" };
  }
  command = inner.command;
  if (command !== XTHB_CMD_PLAY && command !== XTHB_CMD_UPDATE &&
    command !== XTHB_CMD_STOP && command !== XTHB_CMD_SET_BASELINE &&
    command !== XTHB_CMD_STOP_ALL && command !== XTHB_CMD_TEST) {
    return { error: "unsupported_command" };
  }
  if (!xthbIsSafeId(inner.source, XTHB_MAX_ID_CHARS)) {
    return { error: "missing_source" };
  }

  /* stop_all 不需要其他字段 —— 它必须永远能执行。 */
  if (command === XTHB_CMD_STOP_ALL) {
    return { command: command, source: inner.source, eventId: null, targets: null, sequence: null };
  }

  if (command === XTHB_CMD_STOP) {
    hasEventId = xthbHasOwn(inner, "eventId") && inner.eventId !== null;
    if (hasEventId && !xthbIsSafeId(inner.eventId, XTHB_MAX_ID_CHARS)) {
      return { error: "missing_event_id" };
    }
    if (xthbHasOwn(inner, "targets") && inner.targets !== null) {
      /* stop 的 targets 是选择器：不需要驱动指标。 */
      targets = xthbParseTargets(inner.targets, false);
      if (targets.error) {
        return { error: "invalid_targets" };
      }
      targets = targets.targets;
    }
    /* 选择器校验放在解析阶段，否则会拖到执行阶段变成静默成功。 */
    if (!hasEventId && targets === null) {
      return { error: "missing_stop_selector" };
    }
    /* 空 targets 数组同样没有选择器 —— 也在解析阶段就拒绝。 */
    if (!hasEventId && targets.length === 0) {
      return { error: "missing_stop_selector" };
    }
    return {
      command: command,
      source: inner.source,
      eventId: hasEventId ? inner.eventId : null,
      targets: targets,
      sequence: null
    };
  }

  /*
   * test 是"只校验不驱动"的预检命令（docs/02 §5），不带 sequence 也合法 ——
   * 它不改变任何状态，没有"新旧"可言。
   */
  if (command !== XTHB_CMD_TEST) {
    if (!xthbIsFiniteNumber(inner.sequence) || inner.sequence < 0) {
      return { error: "invalid_sequence" };
    }
    seq = inner.sequence;
  } else if (xthbHasOwn(inner, "sequence")) {
    if (!xthbIsFiniteNumber(inner.sequence) || inner.sequence < 0) {
      return { error: "invalid_sequence" };
    }
    seq = inner.sequence;
  }

  if (command === XTHB_CMD_SET_BASELINE || command === XTHB_CMD_TEST) {
    if (!xthbHasOwn(inner, "targets") || inner.targets === null) {
      return { error: "missing_targets" };
    }
    /* 空数组是合法的：set_baseline 的空快照 = 清空该来源基线（docs/02 §5）。 */
    targets = xthbParseTargets(inner.targets, true);
    if (targets.error) {
      return { error: "invalid_targets" };
    }
    return {
      command: command, source: inner.source, eventId: null,
      targets: targets.targets, sequence: seq
    };
  }

  /* play / update */
  if (!xthbIsSafeId(inner.eventId, XTHB_MAX_ID_CHARS)) {
    return { error: "missing_event_id" };
  }
  if (!xthbHasOwn(inner, "targets") || inner.targets === null) {
    return { error: "missing_targets" };
  }
  targets = xthbParseTargets(inner.targets, true);
  if (targets.error) {
    return { error: "invalid_targets" };
  }
  /*
   * play/update 必须至少有一个目标：空数组会让下面这个循环一次都不执行，
   * maxDuration 停在 0，于是一个"什么也不做"的命令被当成 accepted，
   * 还白白占掉一个事件名额（docs/02 §3 要求每个目标有正 durationMs）。
   */
  if (targets.targets.length === 0) {
    return { error: "missing_targets" };
  }
  for (index = 0; index < targets.targets.length; index = index + 1) {
    durationMs = targets.targets[index].durationMs;
    if (!xthbIsFiniteNumber(durationMs) || durationMs <= 0) {
      return { error: "invalid_duration" };
    }
    if (durationMs > maxDuration) {
      maxDuration = durationMs;
    }
  }
  return {
    command: command,
    source: inner.source,
    eventId: inner.eventId,
    targets: targets.targets,
    sequence: seq,
    durationMs: maxDuration
  };
}

function xthbExecute(parsed) {
  var nowMs;
  var partFinishAtMs;
  var index;
  var target;

  if (parsed.command === XTHB_CMD_STOP_ALL) {
    /*
     * 紧急全停：清掉所有基线与【活跃事件】，写零并推给设备。
     *
     * **栅栏表刻意不清**：它的职责是"拒绝旧 sequence 的重放"，
     * 清掉等于让停机的瞬间成为重放窗口 —— 那正是要防的场景。
     * 栅栏由自己的保留期（xthbTrimFence）负责回收。
     */
    xthbEvents = {};
    xthbBaselines = {};
    xthbLog("stop_all：状态已清空，正在把归零推给输出 Job（不保证设备已收到）");
    /*
     * 真实推送一次归零（forcePush 让本轮绕过"值没变就跳过"），
     * 然后把零状态记进 xthbWritten，避免下一个 tick 重复推一遍。
     * 最后才写状态：推送过程即使抛异常（宿主调用已被包住），
     * 也不会出现"状态说停了、实际还在输出"。
     */
    /* 状态刚被清空，缓存必须失效，否则会按清空前的候选算出输出。 */
    xthbResetCandidateCache();
    xthbForcePush = true;
    xthbPushOutputs(xthbComputeOutputs(nowMs = xthbNowMs()));
    XTHB_setVariable("xthb-status", "stopped_all");
    xthbWriteDiagnostics();
    return { ok: true, code: "stopped_all" };
  }

  if (parsed.command === XTHB_CMD_TEST) {
    /* 只校验不驱动硬件：不写输出变量、不启动 Job、也不留痕（它没被接受为状态）。 */
    return { ok: true, code: "validated" };
  }

  if (parsed.command === XTHB_CMD_SET_BASELINE) {
    xthbNoteTargetIgnores(parsed.targets, "baseline");
    return xthbApplyBaseline(parsed.source, parsed.sequence, xthbTargetsToParts(parsed.targets));
  }

  if (parsed.command === XTHB_CMD_STOP) {
    return xthbApplyStop(parsed.source, parsed.eventId,
      parsed.targets === null ? null : xthbTargetsToParts(parsed.targets));
  }

  /* play / update 语义相同：整集替换，靠 sequence 判断新旧。 */
  nowMs = xthbNowMs();
  xthbNoteTargetIgnores(parsed.targets, "event " + parsed.eventId);
  /*
   * 每个部位各自的到期时刻。docs/02 §3 把 durationMs 定义在 target 上，
   * 所以 200ms 的一击不能在同一个事件里被 5000ms 的另一个部位拖着继续输出。
   */
  partFinishAtMs = {};
  for (index = 0; index < parsed.targets.length; index = index + 1) {
    target = parsed.targets[index];
    partFinishAtMs[target.part] = nowMs + target.durationMs;
  }
  return xthbApplyPlay(parsed.source, parsed.eventId, parsed.sequence,
    xthbTargetsToParts(parsed.targets), nowMs + parsed.durationMs, partFinishAtMs);
}

/*
 * Final Actions 调这个：脚本停止时把所有音量归零，并把归零推给输出 Job。
 *
 * 注意这里必须【真的推送】一次（forcePush 绕过"值没变就跳过"）：只改变量
 * 而不启动输出 Job，零值就永远到不了设备。推送后 xthbWritten 已记录零状态，
 * 所以随后的 tick 不会再重复推一遍。
 */
function xtoysBridgeStopAll() {
  /* 与 stop_all 同理：清活跃事件与基线，栅栏交给它自己的保留期回收。 */
  xthbEvents = {};
  xthbBaselines = {};

  if (xthbConfig === null) {
    /* 配置坏了也要尽量写零；Final Actions 的显式 UI 归零才是硬保障。 */
    xthbForcePush = false;
    xthbLog("停止：配置未成功加载，仅写入状态");
    XTHB_setVariable("xthb-status", "stopped");
    return "stopped";
  }
  xthbWriteZerosAndRecord();
  xthbResetCandidateCache();
  xthbForcePush = true;
  xthbPushOutputs(xthbComputeOutputs(xthbNowMs()));
  XTHB_setVariable("xthb-status", "stopped");
  xthbWriteDiagnostics();
  xthbLog("已把全部音量写零并推给输出 Job；硬件归零另有 Final Actions 的显式 Action 兜底");
  return "stopped";
}
